/**
 * Frozen snapshot of the demo traces as ready-to-POST OTLP v2 bodies: a multi-agent
 * AI Service Desk run across two tenants, 17 spans each. Four agents (triage,
 * identity, knowledge, notification) hand off to each other, each making one
 * gpt-6.1-sol call and one tool call, plus a RAG embedding. Source of truth for the
 * traces portion of `respan demo`.
 *
 * Span names follow the SDKs' semantic style (`llm.<model>`, `agent.<name>`,
 * `tool.<name>`, `handoff.<from>_to_<to>`, `embedding`; see
 * contribution/writing-instrumentations.md), and handoff spans carry
 * `respan.entity.log_type: handoff`. Derived from the team's original
 * `trace-bodies/` dataset by dropping the Vercel AI SDK wrapper spans
 * (`ai.generateText`, `ai.embed`) and moving the LLM calls to gpt-6.1-sol.
 *
 * Each `body` is a complete OTLP/JSON payload for `POST /api/v2/traces`. The
 * seeder (`seed-traces.ts`) re-stamps fresh trace/span ids and recent
 * timestamps on each fresh seed, and sets the root span's name to `workflow` (below)
 * so it shows in the dashboard Workflow column and is unique per trace — the dataset
 * repeats some scenarios with a byte-identical root span, and a unique root name keeps
 * the platform from rejecting it as a duplicate workflow span.
 *
 * The filterable `span_workflow_name` marker stays a shared constant (see seed-traces.ts)
 * so dedup, teardown, and the dashboard link match all demo traces at once.
 *
 * Frozen snapshot: not regenerated at build time, imported directly. No runtime JSON.
 */

/** A complete OTLP/JSON trace body for `POST /api/v2/traces`. */
export interface OtlpTraceBody {
  resourceSpans: Record<string, unknown>[];
}

/** One demo trace. */
export interface DemoTraceFixture {
  /** Human label for the seed summary. */
  name: string;
  /** Unique workflow id set as the root span name (shown in the Workflow column). */
  workflow: string;
  /** The OTLP body to ingest. */
  body: OtlpTraceBody;
}

